<?php
declare(strict_types=1);
final class TaxonomyValidator{public static function data(array $input,string $type):array{$name=trim((string)($input['name']??''));if($name===''||mb_strlen($name)>160)throw new InvalidArgumentException('El nombre es obligatorio y no puede exceder el límite permitido.');$slug=SlugService::make((string)($input['slug']??$name));if($slug===''||!Validator::slug($slug))throw new InvalidArgumentException('El slug no es válido.');if($type==='brand'&&!empty($input['website_url'])&&!filter_var($input['website_url'],FILTER_VALIDATE_URL))throw new InvalidArgumentException('El sitio web no es válido.');if(!empty($input['website_url'])&&!preg_match('#^https?://#i',$input['website_url']))throw new InvalidArgumentException('El sitio web debe usar HTTP o HTTPS.');return ['name'=>$name,'slug'=>$slug];}}
